import sqlite3
import os
import difflib
import uuid
from datetime import datetime, timezone
from flask import Flask, request, jsonify, g, abort, redirect, url_for
from markupsafe import escape

app = Flask(__name__)
DATABASE = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'db.sqlite3')


def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
        db.execute('PRAGMA foreign_keys = ON')
    return db


@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()


def init_db():
    with app.app_context():
        db = get_db()
        db.executescript('''
            CREATE TABLE IF NOT EXISTS entries (
                id TEXT PRIMARY KEY,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                created_by TEXT NOT NULL,
                last_modified_by TEXT NOT NULL,
                last_modified_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS edits (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                entry_id TEXT NOT NULL,
                content TEXT NOT NULL,
                modified_by TEXT NOT NULL,
                summary TEXT NOT NULL,
                modified_at TEXT NOT NULL,
                FOREIGN KEY (entry_id) REFERENCES entries(id) ON DELETE CASCADE
            );
        ''')
        db.commit()


def now_iso():
    return datetime.now(timezone.utc).isoformat()


def entry_to_dict(row):
    return {
        'id': row['id'],
        'title': row['title'],
        'content': row['content'],
        'lastModifiedBy': row['last_modified_by'],
        'lastModifiedAt': row['last_modified_at'],
    }


def render_page(title, body):
    return f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>{escape(title)}</title>
<style>
body {{ font-family: sans-serif; max-width: 900px; margin: 2em auto; padding: 0 1em; }}
pre {{ background: #f4f4f4; padding: 1em; overflow-x: auto; }}
.diff-add {{ color: #0a7a0a; }}
.diff-del {{ color: #a10a0a; }}
nav a {{ margin-right: 1em; }}
</style>
</head>
<body>
<nav><a href="/entries">All Entries</a></nav>
{body}
</body>
</html>'''


@app.route('/entries', methods=['GET'])
def list_entries():
    db = get_db()
    rows = db.execute('SELECT id, title FROM entries ORDER BY title COLLATE NOCASE').fetchall()
    items = ''.join(
        f'<li><a href="/entries/{escape(r["id"])}">{escape(r["title"])}</a></li>'
        for r in rows
    )
    body = f'<h1>Wiki Entries</h1><ul>{items if items else "<li>No entries yet.</li>"}</ul>'
    return render_page('Wiki Entries', body), 200, {'Content-Type': 'text/html; charset=utf-8'}


@app.route('/entries', methods=['POST'])
def create_entry():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid JSON body'}), 400
    title = data.get('title')
    content = data.get('content')
    created_by = data.get('createdBy')
    if not isinstance(title, str) or not title.strip():
        return jsonify({'error': 'title is required'}), 400
    if not isinstance(content, str):
        return jsonify({'error': 'content is required'}), 400
    if not isinstance(created_by, str) or not created_by.strip():
        return jsonify({'error': 'createdBy is required'}), 400

    entry_id = uuid.uuid4().hex
    ts = now_iso()
    db = get_db()
    try:
        db.execute(
            'INSERT INTO entries (id, title, content, created_by, last_modified_by, last_modified_at) '
            'VALUES (?, ?, ?, ?, ?, ?)',
            (entry_id, title, content, created_by, created_by, ts),
        )
        db.execute(
            'INSERT INTO edits (entry_id, content, modified_by, summary, modified_at) '
            'VALUES (?, ?, ?, ?, ?)',
            (entry_id, content, created_by, 'Initial creation', ts),
        )
        db.commit()
    except sqlite3.Error:
        db.rollback()
        return jsonify({'error': 'Database error'}), 500

    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    return jsonify(entry_to_dict(row)), 201


@app.route('/entries/<entry_id>', methods=['GET'])
def get_entry(entry_id):
    db = get_db()
    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    if row is None:
        return render_page('Not Found', '<h1>Entry not found</h1>'), 404, {'Content-Type': 'text/html; charset=utf-8'}
    contributors = db.execute(
        'SELECT DISTINCT modified_by FROM edits WHERE entry_id = ? ORDER BY modified_by COLLATE NOCASE',
        (entry_id,),
    ).fetchall()
    contrib_list = ''.join(f'<li>{escape(c["modified_by"])}</li>' for c in contributors)
    body = f'''
<h1>{escape(row["title"])}</h1>
<p><em>Last edited by {escape(row["last_modified_by"])} at {escape(row["last_modified_at"])}</em></p>
<pre>{escape(row["content"])}</pre>
<h2>Contributors</h2>
<ul>{contrib_list}</ul>
<p><a href="/entries/{escape(row["id"])}/edits">View edit history</a></p>
'''
    return render_page(row['title'], body), 200, {'Content-Type': 'text/html; charset=utf-8'}


@app.route('/entries/<entry_id>', methods=['PUT'])
def update_entry(entry_id):
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid JSON body'}), 400
    content = data.get('content')
    modified_by = data.get('modifiedBy')
    summary = data.get('summary')
    if not isinstance(content, str):
        return jsonify({'error': 'content is required'}), 400
    if not isinstance(modified_by, str) or not modified_by.strip():
        return jsonify({'error': 'modifiedBy is required'}), 400
    if not isinstance(summary, str) or not summary.strip():
        return jsonify({'error': 'summary is required'}), 400

    db = get_db()
    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    if row is None:
        return jsonify({'error': 'Entry not found'}), 404

    ts = now_iso()
    try:
        db.execute(
            'UPDATE entries SET content = ?, last_modified_by = ?, last_modified_at = ? WHERE id = ?',
            (content, modified_by, ts, entry_id),
        )
        db.execute(
            'INSERT INTO edits (entry_id, content, modified_by, summary, modified_at) '
            'VALUES (?, ?, ?, ?, ?)',
            (entry_id, content, modified_by, summary, ts),
        )
        db.commit()
    except sqlite3.Error:
        db.rollback()
        return jsonify({'error': 'Database error'}), 500

    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    return jsonify(entry_to_dict(row)), 200


@app.route('/entries/<entry_id>/edits', methods=['GET'])
def entry_edits(entry_id):
    db = get_db()
    entry = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    if entry is None:
        return render_page('Not Found', '<h1>Entry not found</h1>'), 404, {'Content-Type': 'text/html; charset=utf-8'}

    edits = db.execute(
        'SELECT * FROM edits WHERE entry_id = ? ORDER BY id ASC', (entry_id,)
    ).fetchall()

    parts = [f'<h1>Edit history for {escape(entry["title"])}</h1>']
    prev_content = ''
    for e in edits:
        diff_lines = difflib.unified_diff(
            prev_content.splitlines(),
            e['content'].splitlines(),
            fromfile='previous',
            tofile='current',
            lineterm='',
        )
        diff_html = []
        for line in diff_lines:
            if line.startswith('+') and not line.startswith('+++'):
                diff_html.append(f'<span class="diff-add">{escape(line)}</span>')
            elif line.startswith('-') and not line.startswith('---'):
                diff_html.append(f'<span class="diff-del">{escape(line)}</span>')
            else:
                diff_html.append(escape(line))
        diff_text = '\n'.join(diff_html)
        parts.append(f'''
<div class="edit">
<h2>Edit by {escape(e["modified_by"])} at {escape(e["modified_at"])}</h2>
<p><strong>Summary:</strong> {escape(e["summary"])}</p>
<pre>{diff_text}</pre>
</div>
''')
        prev_content = e['content']

    return render_page(f'Edits for {entry["title"]}', ''.join(parts)), 200, {'Content-Type': 'text/html; charset=utf-8'}


@app.errorhandler(404)
def not_found(e):
    return render_page('Not Found', '<h1>Not Found</h1>'), 404, {'Content-Type': 'text/html; charset=utf-8'}


@app.errorhandler(500)
def server_error(e):
    return render_page('Server Error', '<h1>Internal Server Error</h1>'), 500, {'Content-Type': 'text/html; charset=utf-8'}


init_db()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
